<?php
// Included only by the labelled disposable Audience HTTP suite.
$searchChecksBefore=$checks;
$searchTerm='Workspace search '.$suffix;
$searchPerson=$campaignStore->savePerson(['email'=>'workspace-'.$suffix.'@example.test','first_name'=>$searchTerm,'last_name'=>'<b>Literal name</b>','email_status'=>'non-subscribed']);
$searchArchived=$campaignStore->savePerson(['email'=>'archived-'.$suffix.'@example.test','first_name'=>$searchTerm,'email_status'=>'non-subscribed']);
$campaignStore->mutatePerson($searchArchived,1,'archive');
$searchDeleted=$campaignStore->savePerson(['email'=>'deleted-'.$suffix.'@example.test','first_name'=>$searchTerm,'email_status'=>'non-subscribed']);
$conn->execute_query('UPDATE marketing_contacts SET deleted_at=UTC_TIMESTAMP() WHERE id=?',[$searchDeleted]);
$searchTitle=$searchTerm.' <script>literal</script>';
$searchCampaign=$campaignStore->createCampaign(['name'=>$searchTitle,'campaign_type'=>'regular']);
$searchRemovedCampaign=$campaignStore->createCampaign(['name'=>$searchTerm.' removed','campaign_type'=>'regular']);
$campaignStore->campaignOperation('delete',[$searchRemovedCampaign],[$searchRemovedCampaign=>1]);
$conn->query("INSERT INTO marketing_audiences(name,settings_json) VALUES ('Search isolation fixture',JSON_OBJECT())");$searchForeignId=(int)$conn->insert_id;
$searchForeign=new AudienceStore($conn,$searchForeignId,1,'Search fixture');
$searchForeign->savePerson(['email'=>'foreign-search-'.$suffix.'@example.test','first_name'=>$searchTerm,'email_status'=>'non-subscribed']);
$searchForeign->createCampaign(['name'=>$searchTerm.' foreign campaign','campaign_type'=>'regular']);
$searchRead=static fn(string $query='',string $category='',?callable $client=null):array=>($client??$editor)('audience.php?'.http_build_query(['api'=>'workspace_search','q'=>$query,'category'=>$category]));
$searchItems=static function(array $response,string $key):array{foreach(json_decode($response['body'],true,32,JSON_THROW_ON_ERROR)['groups'] as $group)if($group['key']===$key)return $group['items'];return [];};
$searchBefore=['person'=>$campaignStore->person($searchPerson)['version'],'campaign'=>$campaignStore->campaign($searchCampaign)['version'],'events'=>(int)$conn->query('SELECT COUNT(*) n FROM marketing_contact_events')->fetch_assoc()['n']];
foreach(['contacts','campaigns','templates'] as $searchView){$searchPage=$editor('audience.php?view='.$searchView);audienceHttpExpect($searchPage['status']===200&&str_contains($searchPage['body'],'data-global-search-open')&&str_contains($searchPage['body'],'id="audience-search"'),'Search dialog available in '.$searchView);}
$searchDoc=new DOMDocument();@$searchDoc->loadHTML($searchPage['body']);$searchMarkup=$searchDoc->saveHTML((new DOMXPath($searchDoc))->query('//*[@id="audience-search"]')->item(0));
audienceHttpExpect(!str_contains($searchMarkup,'Integrations')&&!str_contains($searchMarkup,'Popular integrations')&&!str_contains($searchMarkup,'Not the results you expected'),'Search omits excluded integrations and feedback');
$searchResponse=$searchRead($searchTerm,'connections');$searchPeople=$searchItems($searchResponse,'connections');
audienceHttpExpect($searchResponse['status']===200&&stripos($searchResponse['headers'],'Cache-Control: no-store')!==false,'Authenticated search returns uncached JSON');
audienceHttpExpect(count($searchPeople)===1&&str_contains($searchPeople[0]['href'],'id='.$searchPerson),'Search excludes other audiences, archived and deleted connections');
audienceHttpExpect(str_contains($searchPeople[0]['description'],'<b>Literal name</b>')&&!str_contains($searchResponse['body'],'<b>'),'Search preserves literal names in safe JSON');
audienceHttpExpect(count($searchItems($searchRead(strtoupper($searchTerm),'connections'),'connections'))===1,'Search matches names without case sensitivity');
$searchEmail='workspace-'.$suffix.'@example.test';audienceHttpExpect(count($searchItems($searchRead($searchEmail,'connections'),'connections'))===1,'Search matches email');
audienceHttpExpect($searchItems($searchRead('foreign-search-'.$suffix.'@example.test','connections'),'connections')===[],'Foreign-audience email is not searchable');
$searchCampaignResponse=$searchRead($searchTerm,'campaigns');$searchCampaigns=$searchItems($searchCampaignResponse,'campaigns');
audienceHttpExpect(count($searchCampaigns)===1&&$searchCampaigns[0]['title']===$searchTitle,'Campaign search excludes other audiences and deleted campaigns');
audienceHttpExpect(!str_contains($searchCampaignResponse['body'],'<script>')&&count(json_decode($searchCampaignResponse['body'],true)['groups'])===1,'Campaign filter returns only safely encoded campaign results');
$searchLong=json_decode($searchRead(str_repeat('x',101),'campaigns')['body'],true,32,JSON_THROW_ON_ERROR);audienceHttpExpect($searchLong['groups'][0]['more']===null,'Long search omits a campaign-list link beyond that page’s input limit');
$searchRecent=$searchItems($searchRead(),'campaigns');audienceHttpExpect(count($searchRecent)<=5&&in_array($searchTitle,array_column($searchRecent,'title'),true),'Blank search offers at most five current-account recent campaigns');
audienceHttpExpect(!in_array($searchTerm.' foreign campaign',array_column($searchRecent,'title'),true),'Recent campaigns do not leak another audience');
audienceHttpExpect($searchItems($searchRead(),'connections')===[],'Blank search does not enumerate people');
audienceHttpExpect(count($searchItems($searchRead('Brand Kit','pages'),'pages'))===1,'Available workspace pages are searchable');
audienceHttpExpect(count($searchItems($searchRead('SES','help'),'help'))===2,'Existing SES help articles are searchable');
audienceHttpExpect(count($searchItems($searchRead('','actions'),'actions'))>0,'Editors can find permitted quick actions');
audienceHttpExpect($searchItems($searchRead('','actions',$reviewer),'actions')===[],'Reviewer search does not expose editor quick actions');
$searchReviewerPages=$searchItems($searchRead('','pages',$reviewer),'pages');audienceHttpExpect(!in_array('audience.php?view=import',array_column($searchReviewerPages,'href'),true)&&!in_array('audience.php?view=delivery',array_column($searchReviewerPages,'href'),true),'Reviewer pages omit restricted import and delivery destinations');
audienceHttpExpect(count($searchItems($searchRead($searchTerm,'campaigns',$reviewer),'campaigns'))===1,'Reviewers retain authorized read-only campaign search');
foreach(['api=workspace_search&q%5B%5D=bad','api=workspace_search&category=invalid','api=workspace_search&q='.str_repeat('x',201)] as $invalidSearch)audienceHttpExpect($editor('audience.php?'.$invalidSearch)['status']===400,'Invalid search input is rejected');
audienceHttpExpect($editor('audience.php?api=workspace_search',['q'=>$searchTerm])['status']===405,'Search endpoint is read-only GET');
$searchLiteral=$searchRead("%' OR 1=1 --",'connections');audienceHttpExpect($searchItems($searchLiteral,'connections')===[],'Search treats SQL/wildcard characters literally');
audienceHttpExpect($searchBefore===['person'=>$campaignStore->person($searchPerson)['version'],'campaign'=>$campaignStore->campaign($searchCampaign)['version'],'events'=>(int)$conn->query('SELECT COUNT(*) n FROM marketing_contact_events')->fetch_assoc()['n']],'Search does not change records or write activity events');
$searchAnonymous=curl_init('http://127.0.0.1/audience.php?api=workspace_search');curl_setopt_array($searchAnonymous,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true]);$searchAnonymousBody=curl_exec($searchAnonymous);$searchAnonymousStatus=curl_getinfo($searchAnonymous,CURLINFO_RESPONSE_CODE);
audienceHttpExpect($searchAnonymousStatus===302&&!str_contains($searchAnonymousBody,$searchTitle),'Search requires authentication');
echo 'Workspace search HTTP: '.($checks-$searchChecksBefore)." checks passed.\n";
